"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Silver a golden key', 'author': 'Signature original', 'genre': 'Starlight Tales', 'chapters': [{'n': 1, 'title': 'The Finding', 'text': "They set out at dawn, a golden key in Ivy's pocket, a loyal dog at their side. the Whispering Glade held its breath. love breaks every spell — Ivy didn't know it yet, but they were about to prove it.\n\nIvy found a golden key on the first day of spring, under the oldest oak in the Whispering Glade, where the fireflies danced like sparks. It glowed. Things that glow, Ivy's grandmother always said, are either magic or trouble. Often both.\n\na loyal dog appeared as if called — perhaps by the glow, perhaps by fate. 'That's a golden key,' a loyal dog said, eyes wide. 'The stories say it chooses someone. It seems it chose you.'"}, {'n': 2, 'title': 'The Journey', 'text': "They escaped by constellation-light, laughing and shaking. a golden key glowed brighter, as if proud. Ivy was starting to understand: it wasn't just a magical object. It was a friend, too.\n\nAt the edge of the Whispering Glade, they looked back at the darkened woods and forward at the Thorn Witch's thorn castle. 'Together?' Ivy asked. 'Always,' said a loyal dog. And in they went.\n\nThe path through the Whispering Glade was a storybook: a brook that sang, mushrooms that lit the way, an oak that bowed. a loyal dog knew every tale and told them walking, which made the miles shorter and the dark less dark."}, {'n': 3, 'title': 'The Thorn Castle', 'text': "Ivy held up a golden key. 'Not this,' Ivy said. 'This chose me.' the Thorn Witch laughed — a sound like dead leaves — and sent the shadow crows. a loyal dog met them with the owl's feather and total fearlessness.\n\nThe battle was strange and wonderful: a golden key's light against the Thorn Witch's dark, Ivy's courage against the Thorn Witch's spite, a loyal dog's loyalty against everything. Light, it turns out, is very stubborn.\n\nthe Thorn Witch's castle was made of thorns and sulks. The door asked for a password. a loyal dog guessed 'please' — and it worked, because manners are magic the Thorn Witch never learned."}, {'n': 4, 'title': 'Starlight Restored', 'text': "the Whispering Glade celebrated: the fireflies spelled Ivy's name, the oak dropped acorns of thanks, the wise owl composed a ballad with a loyal dog as the hero — a loyal dog insisted Ivy was the hero; they compromised on both.\n\nThey carried the starlight home to the Whispering Glade in a golden key, which had grown to hold it all. The brook ran forward again. The mushrooms glowed gold. The stars came back, one by one, like friends returning.\n\nlove breaks every spell — Ivy wrote it in the family book, under the date, in the careful letters of someone who means it forever."}, {'n': 5, 'title': 'The Promise Kept', 'text': "New children come to hear the story, and Ivy tells it true: the fear, the laughter, the moment it almost went wrong. 'Were you scared?' they ask. 'Terrified,' Ivy says. 'That's what brave is.'\n\nlove breaks every spell. In the Whispering Glade, in the starlight, in every heart that hears the tale: the promise kept, the story told, the magic real.\n\nthe Whispering Glade thrives: the enchanted forest enchants, the glade whispers kindly, the meadow moonlights. All because one child picked up a golden key and one friend said 'together.'"}, {'n': 6, 'title': 'Bedtime', 'text': "And now it's bedtime in the Whispering Glade, and a golden key glows soft, and a loyal dog is telling the story one more time, to one more sleepy listener. 'The end,' a loyal dog says.\n\nlove breaks every spell. Goodnight.\n\nIvy smiles from the doorway. Outside, the stars are out — all of them, every one, back where they belong. The brook sings. The fireflies dance."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

